import itertools
import json

# Each element is (athlete, contestant, strong, rare_sick, unwell)
# Premises encoded over finite universes of size 1..3:
#   P1: every contestant is a strong athlete (contestant -> athlete & strong)
#   P2: every strong athlete seldom gets sick (strong -> athlete & rare)
#   P3: some athletes are unwell and cannot take part (exists athlete & unwell & not contestant)
#   P4: unwell athletes cannot take part (athlete & unwell -> not contestant)

def premises_hold(model):
    for a, c, s, r, u in model:
        if c and not (a and s):
            return False
        if s and not (a and r):
            return False
        if a and u and c:
            return False
    return any(a and u and not c for a, c, s, r, u in model)

options = {
    # A: some contestants who are unwell seldom get sick
    "A": lambda m: any(c and u and r for a, c, s, r, u in m),
    # B: very few sick contestants took part -> approximated as no sick contestant took part
    "B": lambda m: all((not c) or r for a, c, s, r, u in m),
    # C: some contestants who are rarely sick are unwell
    "C": lambda m: any(c and r and u for a, c, s, r, u in m),
    # D: some strong athletes are unwell
    "D": lambda m: any(s and u for a, c, s, r, u in m),
}

all_models = []
for n in (1, 2, 3):
    for model in itertools.product(itertools.product([0, 1], repeat=5), repeat=n):
        all_models.append(model)

valid = [m for m in all_models if premises_hold(m)]

entailed = {k: all(f(m) for m in valid) for k, f in options.items()}
satisfiable = {k: any(f(m) for m in valid) for k, f in options.items()}

# Cannot be derived: not entailed by the premises, yet consistent with them
candidates = [k for k in options if (not entailed[k]) and satisfiable[k]]
final_answer = candidates[0] if len(candidates) == 1 else "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "premise_models": len(valid),
        "total_models_checked": len(all_models),
        "entailed": entailed,
        "satisfiable_with_premises": satisfiable,
        "non_derivable_candidates": candidates,
        "note": "B uses 'no sick contestant' as a proxy for 'very few sick contestants'",
    },
}

print(json.dumps(result, sort_keys=True))
